import assert from "node:assert/strict";
import { test } from "node:test";
import { run } from "../src/cli.js";
import { createStore } from "../src/store.js";

test("undo after an add replies 'Undid add N' and the task disappears", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  assert.equal(run(["undo"], store), "Undid add 1");
  assert.equal(run(["list"], store), "No tasks.");
});

test("undo after a done replies 'Undid done N' and the task is no longer done", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["done", "1"], store);
  assert.equal(run(["undo"], store), "Undid done 1");
  assert.equal(run(["list"], store), "[ ] 1 Buy milk");
});

test("undo after a remove restores the task's id, title, done mark and place", () => {
  const store = createStore();
  run(["add", "first"], store);
  run(["add", "second"], store);
  run(["add", "third"], store);
  run(["done", "2"], store);
  run(["remove", "2"], store);
  assert.equal(run(["undo"], store), "Undid remove 2");
  assert.equal(
    run(["list"], store),
    "[ ] 1 first\n[x] 2 second\n[ ] 3 third"
  );
});

test("successive undos reverse one action each, in the opposite order", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["done", "1"], store);
  run(["remove", "1"], store);
  assert.equal(run(["undo"], store), "Undid remove 1");
  assert.equal(run(["list"], store), "[x] 1 Buy milk");
  assert.equal(run(["undo"], store), "Undid done 1");
  assert.equal(run(["list"], store), "[ ] 1 Buy milk");
  assert.equal(run(["undo"], store), "Undid add 1");
  assert.equal(run(["list"], store), "No tasks.");
});

test("undo replies 'Nothing to undo.' and changes nothing when the history is empty", () => {
  const store = createStore();
  assert.equal(run(["undo"], store), "Nothing to undo.");
  assert.equal(run(["list"], store), "No tasks.");

  run(["add", "Buy milk"], store);
  run(["undo"], store);
  assert.equal(run(["undo"], store), "Nothing to undo.");
  assert.equal(run(["list"], store), "No tasks.");
});

test("an id whose add was undone is never reused by a later add command", () => {
  const store = createStore();
  run(["add", "one"], store);
  run(["add", "two"], store);
  assert.equal(run(["undo"], store), "Undid add 2");
  assert.equal(run(["add", "three"], store), "Added 3: three");
  assert.equal(run(["list"], store), "[ ] 1 one\n[ ] 3 three");
});

test("a failed command is not something undo reverses", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["add", "Call Sam"], store);
  assert.throws(() => run(["remove", "9"], store), /No task with id 9/);
  assert.equal(run(["undo"], store), "Undid add 2");
  assert.equal(run(["list"], store), "[ ] 1 Buy milk");
  assert.throws(() => run(["explode"], store), /Unknown command: explode/);
  assert.equal(run(["undo"], store), "Undid add 1");
  assert.equal(run(["list"], store), "No tasks.");
});

test("after a failed command with no successful action before it, undo has nothing to reverse", () => {
  const store = createStore();
  assert.throws(() => run(["add"], store), /A task needs a title/);
  assert.throws(() => run(["done", "3"], store), /No task with id 3/);
  assert.equal(run(["undo"], store), "Nothing to undo.");
  assert.equal(run(["list"], store), "No tasks.");
});

test("list is not something undo reverses", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["done", "1"], store);
  assert.equal(run(["list"], store), "[x] 1 Buy milk");
  assert.equal(run(["undo"], store), "Undid done 1");
  assert.equal(run(["list"], store), "[ ] 1 Buy milk");
});

test("after list on a store with nothing to reverse, undo replies 'Nothing to undo.'", () => {
  const store = createStore();
  assert.equal(run(["list"], store), "No tasks.");
  assert.equal(run(["undo"], store), "Nothing to undo.");
});

test("undo ignores extra arguments", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  assert.equal(run(["undo", "1", "junk"], store), "Undid add 1");
  assert.equal(run(["undo", "anything"], store), "Nothing to undo.");
});

test("existing commands keep their replies, effects and errors", () => {
  const store = createStore();
  assert.equal(run(["add", "Buy", "milk"], store), "Added 1: Buy milk");
  assert.equal(run(["add", "Call Sam"], store), "Added 2: Call Sam");
  assert.equal(run(["done", "1"], store), "Completed 1");
  assert.equal(run(["list"], store), "[x] 1 Buy milk\n[ ] 2 Call Sam");
  assert.equal(run(["remove", "2"], store), "Removed 2");
  assert.equal(run(["list"], store), "[x] 1 Buy milk");
  assert.throws(() => run(["done", "abc"], store), /Not a task id: abc/);
  assert.throws(() => run(["remove", "xyz"], store), /Not a task id: xyz/);
  assert.throws(() => run(["explode"], store), /Unknown command: explode/);
  assert.throws(() => run([], store), /Unknown command: \(none\)/);
});

test("commands keep working normally after undo has been used", () => {
  const store = createStore();
  run(["add", "Buy milk"], store);
  run(["done", "1"], store);
  run(["undo"], store);
  assert.equal(run(["done", "1"], store), "Completed 1");
  assert.equal(run(["list"], store), "[x] 1 Buy milk");
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { createStore } from "../src/store.js";

test("undo of an add removes the task it created", () => {
  const store = createStore();
  store.add("Buy milk");
  store.add("Call Sam");
  assert.deepEqual(store.undo(), { type: "add", id: 2 });
  assert.deepEqual(store.all().map((t) => t.id), [1]);
});

test("undo of a done restores the task's prior done value", () => {
  const store = createStore();
  store.add("Buy milk");
  store.complete(1);
  assert.deepEqual(store.undo(), { type: "done", id: 1 });
  assert.deepEqual(
    store.all().map((t) => [t.id, t.title, t.done]),
    [[1, "Buy milk", false]]
  );
});

test("undo of a remove restores id, title, done mark and place in the list", () => {
  const store = createStore();
  store.add("first");
  store.add("second");
  store.add("third");
  store.complete(2);
  store.remove(2);
  assert.deepEqual(store.undo(), { type: "remove", id: 2 });
  assert.deepEqual(
    store.all().map((t) => [t.id, t.title, t.done]),
    [
      [1, "first", false],
      [2, "second", true],
      [3, "third", false],
    ]
  );
});

test("undo reverses one action per call, most recent first", () => {
  const store = createStore();
  store.add("one");
  store.add("two");
  store.complete(1);
  store.remove(2);
  assert.deepEqual(store.undo(), { type: "remove", id: 2 });
  assert.deepEqual(store.undo(), { type: "done", id: 1 });
  assert.deepEqual(store.undo(), { type: "add", id: 2 });
  assert.deepEqual(store.undo(), { type: "add", id: 1 });
  assert.deepEqual(store.all(), []);
  assert.equal(store.undo(), null);
});

test("undo returns null and changes nothing when no action is left to reverse", () => {
  const store = createStore();
  assert.equal(store.undo(), null);
  assert.deepEqual(store.all(), []);

  store.add("one");
  assert.deepEqual(store.undo(), { type: "add", id: 1 });
  assert.equal(store.undo(), null);
  assert.equal(store.undo(), null);
  assert.deepEqual(store.all(), []);
});

test("an id whose add was undone is never reused", () => {
  const store = createStore();
  store.add("one");
  store.add("two");
  store.undo();
  assert.equal(store.add("three").id, 3);
  assert.equal(store.add("four").id, 4);
  assert.deepEqual(store.all().map((t) => t.id), [1, 3, 4]);

  const fresh = createStore();
  fresh.add("only");
  fresh.undo();
  assert.equal(fresh.add("next").id, 2);
});

test("failed store calls record nothing for undo", () => {
  const store = createStore();
  assert.throws(() => store.add("   "), /A task needs a title/);
  assert.equal(store.undo(), null);

  store.add("one");
  assert.throws(() => store.complete(5), /No task with id 5/);
  assert.throws(() => store.remove(5), /No task with id 5/);
  assert.deepEqual(store.undo(), { type: "add", id: 1 });
  assert.equal(store.undo(), null);
});

test("existing store behavior is unchanged", () => {
  const store = createStore();
  const task = store.add("  Buy milk ");
  assert.equal(task.id, 1);
  assert.equal(task.title, "Buy milk");
  assert.equal(task.done, false);
  assert.equal(store.add("Call Sam").id, 2);

  store.complete(2);
  assert.deepEqual(
    store.all().map((t) => [t.id, t.title, t.done]),
    [
      [1, "Buy milk", false],
      [2, "Call Sam", true],
    ]
  );

  const before = store.all();
  assert.throws(() => store.add("   "), /A task needs a title/);
  assert.throws(() => store.complete(7), /No task with id 7/);
  assert.throws(() => store.remove(7), /No task with id 7/);
  assert.deepEqual(store.all(), before);

  store.remove(1);
  assert.equal(store.add("two").id, 3);

  store.all()[0].title = "changed";
  assert.equal(store.all()[0].title, "Call Sam");
});
